-- Verkefnasjóður fluttur í Fundargerðir og skjöl: úthlutanir sem skjöl, lýsing sem inngangur flokksins
UPDATE pages SET parent_id = (SELECT id FROM pages WHERE path = 'um-hsk/fundargerdir'), path = 'um-hsk/fundargerdir/verkefnasjodur', in_menu = 0, body = '<p>Verkefnasjóður HSK var stofnaður á héraðsþingi 26. febrúar 2000. Tilgangur hans er að styrkja félags- og íþróttastarf á sambandssvæði HSK. Sjóðurinn veitir ekki styrki til mannvirkjagerðar; að öðru leyti fer úthlutun eftir mati stjórnar sjóðsins.</p><p><strong>Úthlutað er tvisvar á ári.</strong> Umsóknir þurfa að berast fyrir 1. apríl og 1. október.</p><p><a href="/um-hsk/log-og-reglugerdir#reglugerd-fyrir-verkefnasjod-hsk">Reglugerð fyrir Verkefnasjóð HSK</a></p>' WHERE path = 'um-hsk/verkefnasjodur';
INSERT OR REPLACE INTO redirects (old_key, new_path) VALUES ('path:um-hsk/verkefnasjodur', '/um-hsk/fundargerdir?flokkur=verkefnasjodur');
UPDATE redirects SET new_path = '/um-hsk/fundargerdir?flokkur=verkefnasjodur' WHERE new_path LIKE '/um-hsk/verkefnasjodur%';
UPDATE settings SET value = replace(value, '/um-hsk/verkefnasjodur', '/um-hsk/fundargerdir?flokkur=verkefnasjodur') WHERE key = 'quick_links';
